#!/usr/bin/env python3
"""Build canonical METSI Block F content packages, N26 through N30."""

from __future__ import annotations

import json

import build_block_d_content as base


def u(title, definition, distinction, mechanism, evidence, example, boundary):
    return [title, definition, distinction, mechanism, evidence, example, boundary]


def doc(*, slug, title, question, opening_title, opening, hotel, advance, defer,
        units, instrument_title, instrument_fields, transfer_title, transfer,
        counter_title, counter, errors, referents, references):
    result = base.compact_doc(
        slug=slug, title=title, question=question, opening_title=opening_title,
        opening=opening, hotel=hotel, advance=advance, defer=defer, units=units,
        instrument_title=instrument_title, instrument_fields=instrument_fields,
        transfer_title=transfer_title, transfer=transfer, counter_title=counter_title,
        counter=counter, errors=errors, referents=referents, references=references,
    )
    movement_titles = [
        "Movimiento 1 · Reconocer dependencias y promesas operativas",
        "Movimiento 2 · Construir evidencia y controles proporcionales",
        "Movimiento 3 · Gobernar cambio, degradación y aprendizaje",
    ]
    result["movements"] = [
        [movement_titles[index], units[index * 4:(index + 1) * 4]]
        for index in range(3)
    ]
    result["consequences"] = (
        advance
        + " El avance profesional consiste en sostener una promesa bajo condiciones reales, "
          "con autoridad, evidencia y reparación, no en declarar que la solución quedó disponible."
    )
    result["limits"] = (
        "Ninguna arquitectura, contrato, prueba, control ni tablero elimina el juicio situado. "
        "Las dependencias cambian, la evidencia llega con demora, la operación distribuye poder "
        "y una mejora local puede desplazar daño. El expediente debe conservar población afectada, "
        "supuestos, autoridad, degradación aceptable, reparación y fecha de revisión."
    )
    return result


