def main() -> None:
    base.DOCS = DOCS
    built = {}
    for number, spec in DOCS.items():
        base.build(number, spec)
        built[f"N{number:02d}"] = spec["title"]
    print(json.dumps({"built": built}, ensure_ascii=False))


if __name__ == "__main__":
    main()
